import foliumimport joblibimport pandas as pdimport streamlit as stfrom streamlit_folium import st_foliumfrom tensorflow.keras.models import load_model# ============================================================# STREAMLIT CONFIGURATION# ============================================================st.set_page_config(    page_title="CITY AI SMART TRAFFIC CONTROLLER",    layout="wide")# ============================================================# FILE PATHS# ============================================================TRAFFIC_DATA_PATH = (    r"C:\Users\User\Downloads\final_year_project_mock_traffic_data_v2.csv")LSTM_MODEL_PATH = (    r"C:\Users\User\PycharmProjects\AI_smart_traffic_system"    r"\models\traffic_lstm.keras")LSTM_SCALER_PATH = (    r"C:\Users\User\PycharmProjects\AI_smart_traffic_system"    r"\models\traffic_scaler.pkl")VIDEO_PATH = (    r"C:\Users\User\Videos\Screen Recordings\top-view2.mp4")# ============================================================# CONSTANTS# ============================================================ROUNDABOUT_CENTER = [7.3327756, -2.3278144]LANE_IDS = [    "Lane 1",    "Lane 2",    "Lane 3",    "Lane 4"]FEATURE_COLUMNS = [    "lane_1_avg_density",    "lane_1_volume",    "lane_2_avg_density",    "lane_2_volume",    "lane_3_avg_density",    "lane_3_volume",    "lane_4_avg_density",    "lane_4_volume",]# ============================================================# DATA LOADING# ============================================================@st.cache_datadef load_traffic_data():    """    Loads traffic data from CSV, converts timestamps,    and sorts observations chronologically.    """    df = pd.read_csv(TRAFFIC_DATA_PATH)    df["timestamp"] = pd.to_datetime(df["timestamp"])    df = df.sort_values(        by="timestamp",        ascending=True    ).reset_index(drop=True)    return dfdef get_latest_traffic(df):    """    Returns the most recent traffic observation.    """    return df.iloc[-1]# ============================================================# TRAFFIC DENSITY# ============================================================def get_lane_densities(latest_traffic):    """    Extracts current density for each lane.    """    return {        "Lane 1": float(            latest_traffic["lane_1_avg_density"]        ),        "Lane 2": float(            latest_traffic["lane_2_avg_density"]        ),        "Lane 3": float(            latest_traffic["lane_3_avg_density"]        ),        "Lane 4": float(            latest_traffic["lane_4_avg_density"]        ),    }def get_lane_density_changes(    latest_traffic,    previous_traffic):    """    Calculates the change in traffic density    between the latest and previous observation.    """    return {        "Lane 1": round(            latest_traffic["lane_1_avg_density"]            - previous_traffic["lane_1_avg_density"],            2,        ),        "Lane 2": round(            latest_traffic["lane_2_avg_density"]            - previous_traffic["lane_2_avg_density"],            2,        ),        "Lane 3": round(            latest_traffic["lane_3_avg_density"]            - previous_traffic["lane_3_avg_density"],            2,        ),        "Lane 4": round(            latest_traffic["lane_4_avg_density"]            - previous_traffic["lane_4_avg_density"],            2,        ),    }def format_density_change(change):    """    Formats density change with an explicit + or - sign.    """    return f"{change:+.2f}"# ============================================================# CONGESTION CLASSIFICATION# ============================================================def classify_congestion(density):    """    Converts traffic density into a congestion state.    Project thresholds:    < 10       -> Low    10 - <15   -> Moderate    >= 15      -> High Congestion    """    if density < 10.0:        return "Low"    elif density < 15.0:        return "Moderate"    else:        return "High Congestion"def get_congestion_color(state):    """    Returns a color associated with congestion state.    """    if state == "Low":        return "#28a745"    elif state == "Moderate":        return "#ffc107"    elif state == "High Congestion":        return "#dc3545"    return "#6c757d"# ============================================================# LANE / MAP DATA# ============================================================def build_lanes_data(lane_densities):    lanes = {        "Lane 1": {            "name": "Kumasi Road Approach",            "coords": [                7.3326701,                -2.3276250            ],            "corridor_polygon": [                [7.33220, -2.32710],                [7.33235, -2.32695],                [7.33275, -2.32755],                [7.33260, -2.32770],            ],            "direction": "Southeast → Roundabout",            "density": lane_densities["Lane 1"],            "state": classify_congestion(                lane_densities["Lane 1"]            ),        },        "Lane 2": {            "name": "Sunyani CBD / Township Approach",            "coords": [                7.3329172,                -2.3276572            ],            "corridor_polygon": [                [7.33280, -2.32680],                [7.33305, -2.32680],                [7.33305, -2.32760],                [7.33280, -2.32760],            ],            "direction": "East → Roundabout",            "density": lane_densities["Lane 2"],            "state": classify_congestion(                lane_densities["Lane 2"]            ),        },        "Lane 3": {            "name": "Berekum Road Approach",            "coords": [                7.3339371,                -2.3291834            ],            "corridor_polygon": [                [7.33380, -2.32930],                [7.33405, -2.32910],                [7.33310, -2.32800],                [7.33290, -2.32815],            ],            "direction": "Northwest → Roundabout",            "density": lane_densities["Lane 3"],            "state": classify_congestion(                lane_densities["Lane 3"]            ),        },        "Lane 4": {            "name": "Atronie Road Approach",            "coords": [                7.3325883,                -2.3279298            ],            "corridor_polygon": [                [7.33220, -2.32830],                [7.33235, -2.32845],                [7.33270, -2.32800],                [7.33250, -2.32785],            ],            "direction": "Southwest → Roundabout",            "density": lane_densities["Lane 4"],            "state": classify_congestion(                lane_densities["Lane 4"]            ),        },    }    # Add congestion color after state calculation    for lane in lanes:        lanes[lane]["color"] = get_congestion_color(            lanes[lane]["state"]        )    return lanes# ============================================================# LSTM MODEL# ============================================================@st.cache_resourcedef load_lstm_model():    """    Loads the trained LSTM model once and caches it.    """    return load_model(LSTM_MODEL_PATH)@st.cache_resourcedef load_lstm_scaler():    """    Loads the scaler used during LSTM training.    """    return joblib.load(LSTM_SCALER_PATH)def prepare_prediction_sequence(df, scaler):    """    Creates the last 10 observations required by    the LSTM model.    Output shape:    (1, 10, 8)    """    recent_data = df[FEATURE_COLUMNS].tail(10)    scaled_data = scaler.transform(        recent_data    )    return scaled_data.reshape(        1,        10,        8    )def predict_next_traffic(    sequence,    model,    scaler):    """    Predicts the next traffic observation and    converts predictions back to original units.    """    prediction_scaled = model.predict(        sequence,        verbose=0    )    return scaler.inverse_transform(        prediction_scaled    )def get_predicted_lane_densities(predicted_traffic):    return {        "Lane 1": float(            predicted_traffic[0][0]        ),        "Lane 2": float(            predicted_traffic[0][2]        ),        "Lane 3": float(            predicted_traffic[0][4]        ),        "Lane 4": float(            predicted_traffic[0][6]        ),    }def get_predicted_congestions(    predicted_lane_densities):    return {        lane: classify_congestion(            density        )        for lane, density        in predicted_lane_densities.items()    }# ============================================================# ROUTE RECOMMENDATION# ============================================================def recommended_route(    predicted_lane_densities):    """    Recommends the lane with the lowest predicted    traffic density.    """    recommended_lane = min(        predicted_lane_densities,        key=predicted_lane_densities.get    )    recommended_density = (        predicted_lane_densities[            recommended_lane        ]    )    return (        recommended_lane,        recommended_density    )# ============================================================# ADAPTIVE TRAFFIC SIGNAL CONTROLLER# ============================================================def calculate_3color_adaptive_signals(    lane_densities,    predicted_lane_densities):    """    Determines the current adaptive signal phase using    current and predicted traffic demand.    """    # Combine current and predicted demand.    effective_densities = {        lane: max(            lane_densities[lane],            predicted_lane_densities[lane]        )        for lane in lane_densities    }    highest_lane = max(        effective_densities,        key=effective_densities.get    )    max_density = effective_densities[highest_lane]    signals = {}    # -----------------------------------------    # MODE 1: NORMAL TRAFFIC    # -----------------------------------------    if max_density < 10.0:        for lane in lane_densities:            signals[lane] = {                "status": "🟢 GREEN (Normal Cycle)",                "duration": "20 Seconds",                "color": "green",                "mode": "Normal Operation",                "effective_density": effective_densities[lane],            }        return signals    # -----------------------------------------    # MODE 2: MODERATE CONGESTION    # -----------------------------------------    if 10.0 <= max_density < 15.0:        green_time = 40    # -----------------------------------------    # MODE 3: HIGH CONGESTION    # -----------------------------------------    else:        green_time = 60    # -----------------------------------------    # PRIORITY PHASE    # -----------------------------------------    for lane in lane_densities:        if lane == highest_lane:            signals[lane] = {                "status": "🟢 GREEN (Priority Extended)",                "duration": (                    f"{green_time}s Green + "                    "3s Yellow Transition"                ),                "color": "green",                "mode": "Adaptive Priority",                "effective_density": effective_densities[lane],            }        else:            signals[lane] = {                "status": "🔴 RED (Waiting for Phase)",                "duration": (                    f"Next cycle after "                    f"{green_time}s priority"                ),                "color": "red",                "mode": "Normal Cycle",                "effective_density": effective_densities[lane],            }    return signals# ============================================================# SIGNAL UI# ============================================================def render_glowing_signal(signal_text, duration, color="green"):    """Render a glowing adaptive traffic signal status card."""    color_map = {        "green": ("#00FF66", "rgba(0, 255, 102, 0.6)"),        "red": ("#FF3333", "rgba(255, 51, 51, 0.6)"),        "yellow": ("#FFCC00", "rgba(255, 204, 0, 0.6)"),    }    hex_color, glow_color = color_map.get(        color,        ("#00FF66", "rgba(0, 255, 102, 0.6)")    )    html = f"""    <style>        .signal-card {{            background-color: #121212;            color: {hex_color};            border: 2px solid {hex_color};            padding: 14px;            border-radius: 10px;            font-weight: bold;            text-align: center;            box-shadow:                0 0 8px {glow_color},                0 0 18px {glow_color};            margin-top: 10px;            margin-bottom: 10px;        }}        .signal-status {{            font-size: 18px;            margin-bottom: 8px;        }}        .signal-duration {{            color: #CCCCCC;            font-size: 14px;            font-weight: 600;        }}    </style>    <div class="signal-card">        <div class="signal-status">            {signal_text}        </div>        <div class="signal-duration">            {duration}        </div>    </div>    """    st.html(html)# ============================================================# LOAD AND PROCESS TRAFFIC DATA# ============================================================traffic_df = load_traffic_data()latest_traffic = get_latest_traffic(    traffic_df)previous_traffic = traffic_df.iloc[-2]lane_densities = get_lane_densities(    latest_traffic)lane_changes = get_lane_density_changes(    latest_traffic,    previous_traffic)# ============================================================# LOAD LSTM# ============================================================traffic_scaler = load_lstm_scaler()lstm_model = load_lstm_model()# ============================================================# GENERATE LSTM FORECAST# ============================================================prediction_sequence = prepare_prediction_sequence(    traffic_df,    traffic_scaler)predicted_traffic = predict_next_traffic(    prediction_sequence,    lstm_model,    traffic_scaler)predicted_lane_densities = (    get_predicted_lane_densities(        predicted_traffic    ))predicted_congestion = (    get_predicted_congestions(        predicted_lane_densities    ))# ROUTE RECOMMENDATIONrecommended_lane, recommended_density = (    recommended_route(        predicted_lane_densities    ))# LANE DATALANES_DATA = build_lanes_data(    lane_densities)# ADAPTIVE SIGNAL DECISIONSYSTEM_SIGNALS = (    calculate_3color_adaptive_signals(        lane_densities,        predicted_lane_densities    ))# PREDICTION DATAPREDICTION_DATA = {    lane: {        "density":            predicted_lane_densities[lane],        "state":            predicted_congestion[lane],    }    for lane    in LANE_IDS}# MAIN HEADERst.markdown(    "<h1 style='text-align: center;'>"    "AI SMART TRAFFIC CONTROLLER"    "</h1>",    unsafe_allow_html=True,)st.markdown("---")# CAMERA + MAPcol1, col2 = st.columns(    [1, 1])# CAMERAwith col1:    st.subheader(        "AI-Analyzed Traffic Camera Feed"    )    st.video(        VIDEO_PATH    )# INTERACTIVE MAPwith col2:    st.subheader(        "Interactive COCOBOD Intersection Map"    )    map_objects = folium.Map(        location=ROUNDABOUT_CENTER,        zoom_start=18,        tiles="OpenStreetMap"    )    # Roundabout center    folium.Marker(        location=ROUNDABOUT_CENTER,        popup=(            "<b>Sunyani COCOBOD Roundabout</b>"            "<br>Intersection Control Center"        ),        tooltip=(            "COCOBOD Roundabout Center"        ),        icon=folium.Icon(            color="black",            icon="info-sign"        )    ).add_to(map_objects)    # LANE POLYGONS    for lane_id, data in LANES_DATA.items():        is_recommended = (            lane_id == recommended_lane        )        if is_recommended:            border_color = "#007BFF"            border_weight = 5            route_label = (                "★ RECOMMENDED ROUTE"            )        else:            border_color = data["color"]            border_weight = 2            route_label = data["state"]        signal_info = (            SYSTEM_SIGNALS[lane_id]        )        predicted_density = (            predicted_lane_densities[lane_id]        )        predicted_state = (            predicted_congestion[lane_id]        )        # Detailed lane popup        popup_html = f"""        <div style="            width: 280px;            font-family: Arial;        ">            <h4 style="                margin-bottom: 8px;            ">                {lane_id}            </h4>            <b>{data['name']}</b>            <hr>            <b>Current Traffic</b><br>            Density:            {data['density']:.2f}            <br>            State:            {data['state']}            <br><br>            <b>LSTM Forecast</b><br>            Next ~1 minute:            {predicted_density:.2f}            <br>            Predicted State:            {predicted_state}            <br><br>            <b>Adaptive Signal</b><br>            {signal_info['status']}            <br>            Duration:            {signal_info['duration']}            <br>            Mode:            {signal_info['mode']}            <br><br>            <b>Direction</b><br>            {data['direction']}            <br><br>            <b>{route_label}</b>        </div>        """        # Corridor polygon        folium.Polygon(            locations=data[                "corridor_polygon"            ],            color=border_color,            weight=border_weight,            fill=True,            # Keep congestion color visible            # even when route is recommended            fill_color=data["color"],            fill_opacity=0.45,            tooltip=(                f"{lane_id} | "                f"{data['name']} | "                f"{route_label}"            ),            popup=folium.Popup(                popup_html,                max_width=350            )        ).add_to(map_objects)        # Lane marker        folium.Marker(            location=data["coords"],            popup=folium.Popup(                popup_html,                max_width=350            ),            tooltip=(                f"{lane_id} - "                f"{data['name']}"            ),            icon=folium.Icon(                color=(                    "blue"                    if is_recommended                    else "gray"                ),                icon="car",                prefix="fa",            ),        ).add_to(map_objects)    st_folium(        map_objects,        width=640,        height=280    )# CURRENT TRAFFIC ANALYTICSst.markdown("---")st.markdown(    "<h2 style='text-align: center;'>"    "Real-Time Lane Analytics"    "</h2>",    unsafe_allow_html=True,)m1, m2, m3, m4 = st.columns(4)for column, lane in zip(    [m1, m2, m3, m4],    LANE_IDS):    with column:        st.metric(            label=(                f"{lane} "                f"({LANES_DATA[lane]['name']})"            ),            delta=format_density_change(                lane_changes[lane]            ),            value=(                f"{lane_densities[lane]:.2f}"            ),            delta_color="inverse",        )        st.caption(            LANES_DATA[lane]["state"]        )# AI DECISION SUMMARYst.markdown("---")st.markdown(    "<h2 style='text-align: center;'>"    "AI Traffic Decision Summary"    "</h2>",    unsafe_allow_html=True,)summary_col1, summary_col2, summary_col3, summary_col4 = (    st.columns(4))# Highest current densitycurrent_priority_lane = max(    lane_densities,    key=lane_densities.get)with summary_col1:    st.metric(        "Highest Current Demand",        current_priority_lane    )with summary_col2:    st.metric(        "Signal Priority",        max(            SYSTEM_SIGNALS,            key=lambda lane:            SYSTEM_SIGNALS[lane][                "effective_density"            ]        )    )with summary_col3:    st.metric(        "Recommended Route",        recommended_lane    )with summary_col4:    st.metric(        "Forecast Horizon",        "~1 minute"    )# ============================================================# LSTM FORECAST + ADAPTIVE SIGNAL CONTROLLER# ============================================================st.markdown("---")st.markdown(    "<h2 style='text-align: center;'>"    "Next ~1 Minute LSTM Forecast & "    "Adaptive Signal Controller"    "</h2>",    unsafe_allow_html=True,)st.caption(    "The LSTM uses the previous 10 traffic observations "    "to estimate the next traffic observation.")st.markdown("---")prediction_cols = st.columns(4)# ============================================================# FORECAST + SIGNAL CARDS# ============================================================for idx, lane in enumerate(    LANE_IDS):    with prediction_cols[idx]:        st.metric(            f"{lane} FORECAST",            (                f"{PREDICTION_DATA[lane]['density']:.2f}"            )        )        st.caption(            f"State: "            f"{PREDICTION_DATA[lane]['state']}"        )        signal_info = (            SYSTEM_SIGNALS[lane]        )        render_glowing_signal(            signal_info["status"],            signal_info["duration"],            color=signal_info["color"]        )# ============================================================# ROUTE RECOMMENDATION# ============================================================st.markdown("---")st.subheader(    "Route Recommendation")recommended_name = (    LANES_DATA[        recommended_lane    ]["name"])recommended_direction = (    LANES_DATA[        recommended_lane    ]["direction"])st.success(    f"Recommended Route: "    f"{recommended_lane}")st.write(    f"**{recommended_name}**")st.write(    f"Direction: "    f"{recommended_direction}")st.write(    f"Predicted traffic density: "    f"{recommended_density:.2f}")